head.b:skin:
/*
<Group description="Colors and type">
<Variable name="accent.color" description="Accent (green)" type="color" default="#13a560" value="#13a560"/>
<Variable name="dark.color" description="Header and footer" type="color" default="#1c2027" value="#1c2027"/>
<Variable name="link.color" description="Buttons and links (blue)" type="color" default="#1668d9" value="#1668d9"/>
<Variable name="bg.color" description="Page background" type="color" default="#f6f7f8" value="transparent"/>
<Variable name="text.color" description="Text" type="color" default="#1f2328" value="#1f2328"/>
<Variable name="cart.color" description="Add to cart button" type="color" default="#82b541" value="#82b541"/>
<Variable name="preview.color" description="Live preview button" type="color" default="#0084b4" value="#0084b4"/>
<Variable name="radius.size" description="Corner radius" type="length" default="6px" value="6px"/>
<Variable name="body.font" description="Body font" type="font" default="normal 400 14px Inter,system-ui,sans-serif" value="normal 400 14px Inter,system-ui,sans-serif"/>
</Group>
*/
:root{--a:$(accent.color);--d:$(dark.color);--l:$(link.color);--bg:$(bg.color);--t:$(text.color);--r:$(radius.size);--c:$(cart.color);--pv:$(preview.color)}
*{box-sizing:border-box;margin:0}
html{scroll-behavior:smooth;scroll-padding-top:120px}
body{font:$(body.font);color:var(--t);background:var(--bg);-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}a{color:inherit;text-decoration:none}button{font:inherit;cursor:pointer}
:focus-visible{outline:2px solid var(--l);outline-offset:2px}
.w{max-width:1180px;margin:0 auto;padding:0 16px}
.skip{position:absolute;left:-999px}.skip:focus{left:8px;top:8px;background:#fff;padding:8px;z-index:99}
#bar{position:absolute;left:0;top:0;height:3px;width:0;background:var(--a);z-index:2}
.hd{background:var(--d);color:#fff;position:sticky;top:0;z-index:50}
.hd-in{display:flex;align-items:center;gap:24px;height:64px}
.logo{display:flex;align-items:center;gap:10px}.logo svg{width:26px;height:32px}.logo b{font-size:21px;font-weight:700}
.nv{flex:1}.nv ul{display:flex;justify-content:center;gap:28px;list-style:none;padding:0}
.nv li{position:relative}.nv a{display:block;padding:22px 0;font-weight:600;font-size:15px}
.nv li.has>a:after{content:"▾";font-size:10px;margin-left:5px}
.nv li ul{position:absolute;top:100%;left:-12px;background:#fff;color:var(--t);min-width:190px;padding:6px;border-radius:var(--r);box-shadow:0 10px 30px #0004;display:none;flex-direction:column;gap:0}
.nv li:hover>ul{display:flex}.nv li li a{padding:9px 12px;font-weight:500}.nv li li a:hover{background:var(--bg);color:var(--a)}
.hd-r{display:flex;gap:10px;align-items:center}
.pill{background:#363b45;padding:9px 16px;border-radius:6px;font-weight:600;font-size:14px;transition:background .2s}.pill:hover{background:var(--a)}
.sbtn,.burger{background:none;border:0;color:#fff;padding:6px;display:grid;place-items:center}.burger{display:none;font-size:22px}
.hs{display:none;background:#262a32;padding:10px 0}.so .hs{display:block}
.hs input{width:100%;padding:12px 16px;border:0;border-radius:6px;font:inherit}
.hero{background:linear-gradient(135deg,var(--a),#0b8a52);color:#fff;text-align:center;padding:72px 16px 60px;position:relative;overflow:hidden}
.hero:before,.hero:after{content:"";position:absolute;border-radius:50%;background:#ffffff14;animation:fl 14s ease-in-out infinite alternate}
.hero:before{width:420px;height:420px;left:-120px;top:-180px}.hero:after{width:300px;height:300px;right:-80px;bottom:-140px;animation-delay:-6s}
.hero .widget{position:relative;z-index:1}
.hero h1{font-size:clamp(26px,4.4vw,40px);font-weight:800;line-height:1.2;max-width:820px;margin:0 auto 14px}
.hs2{max-width:600px;margin:26px auto 22px;display:flex;background:#fff;border-radius:40px;padding:5px;box-shadow:0 8px 30px #0003}
.hs2 input{flex:1;min-width:0;border:0;outline:0;padding:12px 20px;border-radius:40px;font:inherit}.hs2 button{border:0;background:none;padding:0 16px;color:#777}
.hero small a{text-decoration:underline}
.in .hero{display:none}
.bar{padding:14px 0 12px;border-bottom:1px solid #e3e5e8}.res{font-size:14px;color:#555;margin-bottom:14px}.res b{color:var(--t)}
.fl{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.fl>b{font-size:15px}.fl small{color:#555;font-size:12px}
.vw{display:flex;gap:4px;margin-left:auto}.vw button{border:0;background:none;color:#999;padding:4px 6px;font-size:18px}.vw .on{color:var(--t)}
.tabs{display:flex;border:1px solid #d7dadf;border-radius:4px;overflow:hidden;background:#fff}
.tabs button{border:0;border-right:1px solid #d7dadf;background:#fff;padding:9px 16px;font-size:13px;font-weight:600;transition:background .2s}
.tabs button:last-child{border:0}.tabs .on{background:#212529;color:#fff}
.crumb{font-size:13px;color:#666;padding:12px 0}.crumb a{color:var(--l)}.crumb .clr{margin-left:12px;text-decoration:underline}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;padding:8px 0 28px}
.card{background:#fff;border-radius:var(--r);box-shadow:0 1px 3px #0001;overflow:hidden;display:flex;flex-direction:column;transition:transform .25s,box-shadow .25s;animation:up .5s both}
.card:nth-child(3n+2){animation-delay:.07s}.card:nth-child(3n){animation-delay:.14s}
.card:hover{transform:translateY(-4px);box-shadow:0 14px 30px #0002}
.th{aspect-ratio:16/9;background:linear-gradient(135deg,#dfe7ee,#eef1f5);position:relative;overflow:hidden;display:block}
.th img{width:100%;height:100%;object-fit:cover;transition:transform .5s}.card:hover .th img{transform:scale(1.05)}
.bdg{position:absolute;top:10px;right:10px;background:#e5484d;color:#fff;font-size:11px;font-weight:700;padding:4px 9px;border-radius:20px}
.cb{padding:14px 14px 12px}.cb h2{font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.by{font-size:12px;color:#8a8f98;margin-top:3px}.by a{color:#8a8f98}.by a:hover{color:var(--l)}
.lb{display:none}.art .lb{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.art .lb a{background:var(--bg);padding:5px 12px;border-radius:20px;font-size:12px;font-weight:600}.art .lb a:hover{background:var(--a);color:#fff}
.mt{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin-top:12px}
.pr{font-size:20px;font-weight:800;display:block}
.st{font-size:13px;letter-spacing:1px;--r:0%;background:linear-gradient(90deg,#f5a623 var(--r),#d5d8dd 0);-webkit-background-clip:text;background-clip:text;color:transparent}
.rt small,.mt>div>small{color:#8a8f98;font-size:12px;display:block}.rt small{display:inline}.dt{display:none!important}
.nm .pr,.nm .rt{display:none}.nm .dt{display:block!important}.nm .sl{display:none}
.ac{display:flex;gap:8px}
.ib{width:38px;height:36px;border:1px solid #d7dadf;border-radius:4px;display:grid;place-items:center;color:#555;transition:all .2s}.ib:hover{border-color:var(--a);color:var(--a)}
.lp{border:1px solid var(--l);color:var(--l);font-weight:700;font-size:13px;padding:0 16px;height:36px;display:inline-flex;align-items:center;border-radius:4px;background:#fff;transition:all .2s}.lp:hover{background:var(--l);color:#fff}
.bb{background:var(--a);color:#fff;font-weight:700;font-size:14px;padding:0 22px;height:40px;display:inline-flex;align-items:center;border-radius:4px}.bb:hover{filter:brightness(.92)}
.grid.list{grid-template-columns:1fr}.list .card{flex-direction:row}.list .th{width:260px;aspect-ratio:auto;flex:none}.list .cb{flex:1}
.pg{display:flex;justify-content:center;gap:8px;padding:6px 0 40px}.pg a,.pg span{min-width:40px;height:40px;display:grid;place-items:center;background:#fff;border:1px solid #e1e4e8;border-radius:4px;padding:0 14px;font-weight:600}.pg a:hover{border-color:var(--a);color:var(--a)}.pg span{background:#f1f3f5}
.none{grid-column:1/-1;text-align:center;padding:50px 0;color:#666}
.art{background:#fff;border-radius:8px;padding:clamp(18px,4vw,40px);margin:24px auto;max-width:820px;box-shadow:0 1px 3px #0001}
.art h1{font-size:clamp(24px,4vw,36px);line-height:1.2;font-weight:800;margin:6px 0 12px}
.pm{display:flex;gap:14px;flex-wrap:wrap;color:#6b7280;font-size:13px}
#act{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}
.pb{font-size:17px;line-height:1.75;margin-top:18px;overflow-wrap:break-word}
.pb img{max-width:100%;height:auto;border-radius:6px;margin:14px auto}.pb h2,.pb h3{margin:28px 0 10px;line-height:1.3}
.pb a{color:var(--l);text-decoration:underline}.pb pre{overflow:auto;background:#10151c;color:#e6edf3;padding:14px;border-radius:6px;font-size:14px}
.pb blockquote{border-left:4px solid var(--a);padding:4px 0 4px 16px;color:#555}.pb table{display:block;overflow:auto;border-collapse:collapse}.pb td,.pb th{border:1px solid #e3e5e8;padding:8px 12px}
.sh{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:22px 0}.sh a,.sh button{border:1px solid #d7dadf;background:#fff;border-radius:4px;padding:8px 14px;font-size:13px;font-weight:600}.sh a:hover,.sh button:hover{border-color:var(--a);color:var(--a)}
.au{border-top:1px solid #e9ebee;padding-top:16px;font-size:14px}
.rl{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px;margin-top:10px}.rl a{display:block;font-weight:600;font-size:13px}.rl img{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:6px;margin-bottom:6px}
.np{display:flex;justify-content:space-between;gap:10px;margin:20px 0}
.cm h3,.rel h3{margin:26px 0 10px;font-size:18px}
.ad{text-align:center;margin:14px auto}
.ft{background:#1c1f25;color:#c9ced6;margin-top:30px;padding-top:40px}
.fg{display:grid;grid-template-columns:2fr 1fr 1fr;gap:32px}
.ft h3{color:#fff;font-size:15px;padding-bottom:10px;border-bottom:1px solid #343944;margin-bottom:14px}
.ft ul{list-style:none;padding:0;display:grid;gap:12px;font-size:13px}.ft li a:hover{color:#fff}
.ft p{margin:8px 0 14px;font-size:14px}
.nl{display:flex;gap:10px;max-width:460px}.nl input{flex:1;min-width:0;background:#272b33;border:1px solid #343944;color:#fff;padding:12px;border-radius:4px;font:inherit}
.nl button{background:var(--a);color:#fff;border:0;padding:0 26px;border-radius:4px;font-weight:700}
.so1{display:flex;gap:10px;margin-top:16px}.so1 a{width:34px;height:34px;display:grid;place-items:center;background:#272b33;border-radius:6px;font-weight:700;color:#fff;transition:background .2s}.so1 a:hover{background:var(--a)}
.fb{background:#14161a;margin-top:34px;padding:16px 0;font-size:12px}.fbi{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.fab{position:fixed;right:18px;bottom:18px;width:52px;height:52px;border-radius:50%;background:var(--a);color:#fff;display:grid;place-items:center;box-shadow:0 6px 20px #0004;z-index:40;transition:transform .2s}.fab:hover{transform:scale(1.08)}
@keyframes up{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes fl{to{transform:translate(40px,30px) scale(1.12)}}
@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.fg{grid-template-columns:1fr 1fr}.fg>:first-child{grid-column:1/-1}}
@media(max-width:820px){.burger{display:grid}.pill{display:none}.nv{display:none;position:absolute;left:0;right:0;top:64px;background:var(--d);padding:8px 16px 16px;flex:none}.mo .nv{display:block}.nv ul{flex-direction:column;gap:0;align-items:stretch}.nv a{padding:12px 0}.nv li ul{position:static;display:flex;background:none;color:#cfd4dc;box-shadow:none;padding:0 0 0 14px}.hd-in{gap:12px}.hd-r{margin-left:auto}.tabs{overflow-x:auto;width:100%}.vw{display:none}}
@media(max-width:600px){.grid{grid-template-columns:1fr}.fg{grid-template-columns:1fr}.list .card{flex-direction:column}.list .th{width:100%;aspect-ratio:16/9}.hero{padding:48px 16px 40px}}
/* ===== POST FEATURES (Mega Mag style + motion) ===== */
.pb .rv{opacity:0}
.pb .rv.v{opacity:1;animation:fi .55s cubic-bezier(.2,.8,.2,1) backwards;animation-delay:calc(var(--i,0)*55ms)}
.pb .fh{font-size:22px;font-weight:400;margin:36px 0 18px;padding-bottom:12px;border-bottom:1px solid #dcdfe3;position:relative;color:#3a3f46}
.pb .fh:after{content:"";position:absolute;left:0;bottom:-1px;height:3px;width:0;background:linear-gradient(90deg,var(--a),var(--l));border-radius:3px;transition:width .9s cubic-bezier(.2,.8,.2,1) .2s}
.pb .fh.v:after{width:96px}
.pb ul.feat{list-style:none;padding:0;margin:0 0 20px;display:grid;gap:2px}
.pb ul.feat.cols{grid-template-columns:1fr}
@media(min-width:700px){.pb ul.feat.cols{grid-template-columns:1fr 1fr;column-gap:18px}}
.pb ul.feat li{position:relative;padding:9px 10px 9px 42px;border-radius:8px;color:#444;font-size:16px;line-height:1.5;transition:background .25s,transform .25s}
.pb ul.feat li:before{content:"\2713";position:absolute;left:9px;top:10px;width:22px;height:22px;border-radius:50%;background:#e4f5ec;color:var(--a);font-size:12px;font-weight:800;display:grid;place-items:center;transition:transform .45s,background .25s,color .25s}
.pb ul.feat li:hover{background:#f2faf6;transform:translateX(6px)}
.pb ul.feat li:hover:before{background:var(--a);color:#fff;transform:rotate(360deg) scale(1.12)}
.pb ul.feat li.v:before{animation:pop .5s cubic-bezier(.3,1.6,.5,1) backwards;animation-delay:calc(var(--i,0)*55ms + 150ms)}
.pb ul.feat a{color:var(--l);font-weight:600;text-decoration:none;border-bottom:1px dashed transparent;transition:border-color .2s}
.pb ul.feat a:hover{border-bottom-color:var(--l)}
.pb ul.show{list-style:none;padding:24px 26px;margin:20px 0;background:linear-gradient(135deg,#14161b,#262b35);border-radius:12px;display:grid;gap:13px;color:#fff;font-weight:600;position:relative;overflow:hidden;isolation:isolate;box-shadow:0 14px 34px #0003}
.pb ul.show:before{content:"";position:absolute;inset:-60%;z-index:-1;background:conic-gradient(from 0deg,transparent 0,#ff9f1c30 12%,transparent 28%,#13a56026 60%,transparent 76%);animation:spin 9s linear infinite}
.pb ul.show li{position:relative;padding-left:26px;transition:transform .25s}
.pb ul.show li:before{content:"\203A";position:absolute;left:4px;top:-3px;color:#ff9f1c;font-size:24px;font-weight:800;transition:transform .25s}
.pb ul.show li:hover{transform:translateX(5px)}
.pb ul.show li:hover:before{transform:translateX(5px)}
.pb p.rate{font-weight:700;margin:26px 0;display:flex;align-items:center;gap:6px;flex-wrap:wrap;background:#fff8e8;border:1px solid #fde7b0;border-radius:10px;padding:12px 16px}
.pb p.rate i{font-style:normal;color:#f5a623;font-size:18px;display:inline-block;animation:tw 1.8s ease-in-out infinite;animation-delay:calc(var(--k)*.16s)}
.art table.spec{display:table;width:100%;border-collapse:collapse;font-size:14px;margin:0}
.art table.spec td,.art table.spec th{border:0;border-bottom:1px solid #eceef1;padding:11px 8px;text-align:left;vertical-align:top;line-height:1.45}
.art table.spec tr:last-child td,.art table.spec tr:last-child th{border-bottom:0}
.art table.spec th,.art table.spec td:first-child{font-weight:700;width:42%;color:var(--t)}
.art table.spec td+td{color:#7b818a;font-weight:400}
.art table.spec a{color:var(--l);text-decoration:none}.art table.spec a:hover{text-decoration:underline}
.art table.spec tr{transition:background .2s}.art table.spec tr:hover{background:#f6f9fb}
.pm .ok{color:var(--a);font-weight:700}.pm .ok:after{content:"\2713";display:inline-grid;place-items:center;width:16px;height:16px;border-radius:50%;background:var(--a);color:#fff;font-size:10px;margin-left:6px;animation:pop .6s .4s cubic-bezier(.3,1.6,.5,1) backwards}
.pm .rtg{display:inline-flex;align-items:center;gap:6px}.pm .rtg .st{font-size:14px}
.art.two{max-width:1180px;display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:34px;align-items:start}
.pcol{min-width:0}
.side{position:sticky;top:84px;display:grid;gap:16px}
.bx{background:#fff;border:1px solid #e3e5e8;border-radius:var(--r);padding:20px;animation:up .6s both}
.bx+.bx{animation-delay:.12s}
.bx h4{font-size:15px;margin-bottom:6px}
.pbox .pp{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e3e5e8;padding-bottom:14px;font-weight:700;color:#555}
.pbox .pp b{font-size:40px;line-height:1;color:var(--t);animation:pop .6s .2s cubic-bezier(.3,1.6,.5,1) backwards}
.pbox ul{list-style:none;padding:0;margin:14px 0 16px;display:grid;gap:9px;font-size:13px;color:#555}
.pbox li{padding-left:24px;position:relative}.pbox li:before{content:"\2713";position:absolute;left:0;top:0;color:var(--a);font-weight:800}
.pbox .bb{width:100%;justify-content:center;height:48px;font-size:15px;gap:8px;position:relative;overflow:hidden;border-radius:6px}
.pbox .bb:after,.pb .btn-buy:after{content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(100deg,transparent,#ffffff70,transparent);transform:skewX(-20deg);animation:sh 3.4s ease-in-out infinite}
.pbox .lp{width:100%;justify-content:center;margin-top:10px;height:42px}
.pbox small{display:block;text-align:center;font-style:italic;color:#8a8f98;font-size:12px;margin-top:12px}
@media(min-width:901px){.art.two #act{display:none}}
@media(max-width:900px){.art.two{display:block}.side{position:static;margin-top:26px}}
@keyframes fi{from{opacity:0;transform:translateX(-18px)}to{opacity:1;transform:none}}
@keyframes pop{from{transform:scale(0)}to{transform:scale(1)}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes tw{0%,60%,100%{transform:scale(1) rotate(0)}30%{transform:scale(1.4) rotate(14deg);filter:brightness(1.25)}}
@keyframes sh{0%,55%{left:-60%}100%{left:130%}}
/* ===== ITEM PAGE LAYOUT (reference recreation) ===== */
.art.two{background:none;box-shadow:none;padding:0 16px;margin:18px auto 30px;gap:0 32px;grid-template-columns:minmax(0,1fr) 340px}
.art.two .phd,.art.two .ptabs{grid-column:1/-1}
.phd h1{font-size:clamp(24px,3.4vw,32px);font-weight:700;margin:4px 0 10px}
.phd .pm{font-size:15px;align-items:center;gap:20px}.phd .pm>span:first-child{font-size:16px}
.phd .pm>span:first-child:before{content:"By ";color:#6b7280}
.ptabs{display:flex;align-items:center;gap:2px;border-bottom:1px solid #dfe2e6;background:var(--bg);position:sticky;top:64px;z-index:20;margin:12px 0 24px;overflow-x:auto;white-space:nowrap;scrollbar-width:none}
.ptabs::-webkit-scrollbar{display:none}
.ptabs a,.ptabs button{display:inline-flex;align-items:center;gap:6px;padding:14px 16px;font-size:13px;font-weight:600;color:#555;border:1px solid transparent;border-bottom:0;background:none;border-radius:4px 4px 0 0;transition:color .2s,background .2s}
.ptabs a:hover,.ptabs button:hover{color:var(--l)}
.ptabs .on{background:#fff;border-color:#dfe2e6;color:var(--t);margin-bottom:-1px;position:relative}
.ptabs .on:after{content:"";position:absolute;left:0;right:0;top:-1px;height:2px;background:var(--a);animation:gw .4s both}
.ptabs .nb{background:#0b7ba8;color:#fff;font-size:11px;font-weight:700;line-height:1;padding:3px 6px;border-radius:3px}
.ptabs .sp{margin-left:auto}.ptabs .sp~a,.ptabs .sp~button{margin-left:0}
.ptabs svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;transition:transform .3s}
.ptabs .fav.on{color:#e5484d;background:none;border-color:transparent;margin-bottom:0}.ptabs .fav.on:after{display:none}
.ptabs .fav.on svg{fill:#e5484d;animation:pop .5s cubic-bezier(.3,1.6,.5,1)}
.pvw{border:1px solid #e3e5e8;background:#fff;border-radius:var(--r);padding:12px 12px 18px;text-align:center;margin-bottom:28px;overflow:hidden;animation:up .6s both}
.pvw img{margin:0 auto;border-radius:4px;height:auto;width:100%;transition:transform .7s cubic-bezier(.2,.8,.2,1)}.pvw:hover img{transform:scale(1.025)}
.pvw a:not(.pvb){display:block;overflow:hidden;border-radius:4px}
.pvb{display:inline-flex;align-items:center;gap:10px;margin-top:16px;background:var(--pv);color:#fff;border:0;height:40px;padding:0 26px;border-radius:3px;font-weight:600;font-size:14px;transition:transform .2s,box-shadow .2s}
.pvb:hover{transform:translateY(-2px);box-shadow:0 8px 18px #0084b440}
.art.two .pb{margin-top:0;font-size:16px;color:#555}
.pbox .pw{display:flex;align-items:flex-start;color:var(--t)}.pbox .pw sup{font-size:14px;margin:4px 2px 0 0;font-weight:600}
.pbox .lic{font-size:16px;font-weight:600;color:#555}
.pbox .bump{animation:bmp .45s ease}
.pbox .bb{background:var(--c);border-bottom:3px solid #0003;margin-top:14px}
.pbox .lp{border-color:var(--pv);color:var(--pv)}.pbox .lp:hover{background:var(--pv);color:#fff}
.ext{display:flex;gap:10px;align-items:center;font-size:14px;margin:14px 0 4px;cursor:pointer;line-height:1.3}
.ext input{width:18px;height:18px;accent-color:var(--c);flex:none}.ext span{flex:1}.ext s{color:#999;font-size:13px}.ext b{margin-left:6px;font-size:17px}
.qty label{font-weight:700;font-size:13px;display:block;margin:16px 0 8px}
.qc{display:flex;gap:8px}.qc button{width:34px;height:34px;border-radius:50%;border:1px solid #cfd3d8;background:#fff;font-size:18px;line-height:1;flex:none;transition:all .2s}.qc button:hover{border-color:var(--c);color:var(--c);transform:scale(1.1)}
.qc input{flex:1;min-width:0;height:34px;border:1px solid #cfd3d8;border-radius:4px;text-align:center;font:inherit;color:#555}
.acd{display:flex;flex-wrap:wrap;gap:14px;align-items:center}
.av{width:62px;height:62px;border-radius:12px;background:linear-gradient(135deg,var(--a),var(--l));color:#fff;font-weight:800;font-size:28px;display:grid;place-items:center;transition:transform .4s}.acd:hover .av{transform:rotate(-6deg) scale(1.06)}
.acd b{font-size:20px}
.acd .pfb{width:100%;text-align:center;background:#e9ebee;border-bottom:3px solid #cdd1d6;border-radius:4px;padding:11px;font-weight:600;color:#555;transition:all .25s}.acd .pfb:hover{background:var(--l);border-color:#0003;color:#fff}
.cpr{text-align:center;font-size:12px;color:#666;line-height:1.7}.cpr a{color:var(--l)}
.side{top:122px}
@keyframes gw{from{transform:scaleX(0)}to{transform:none}}
@keyframes bmp{50%{transform:scale(1.15)}}
@media(max-width:900px){.ptabs{top:64px}.ptabs .sp{margin-left:12px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

body.script:
//
(function(){
var d=document,q=function(s,c){return(c||d).querySelector(s)},qa=function(s,c){return[].slice.call((c||d).querySelectorAll(s))};
var on=function(el,f){el&&el.addEventListener('click',f)};
on(q('.burger'),function(){d.body.classList.toggle('mo')});
on(q('.sbtn'),function(){d.body.classList.toggle('so');var i=q('.hs input');i&&i.focus()});
qa('#menu li').forEach(function(li){var a=q('a',li);if(a&&a.textContent.charAt(0)=='_'){a.textContent=a.textContent.slice(1);var p=li.previousElementSibling;if(p){var u=q('ul',p)||p.appendChild(d.createElement('ul'));u.appendChild(li);p.classList.add('has')}}});
var M=/^(price|sales|rating|reviews|badge|extend)-(.+)$/i;
function meta(root){var m={},cat=null;qa('.lb a',root).forEach(function(x){var r=M.exec(x.textContent.trim());if(r){m[r[1].toLowerCase()]=r[2];x.parentNode.removeChild(x)}else if(!cat)cat=x});return{m:m,cat:cat}}
var g=q('#grid');
if(g){
var cs=qa('.card',g);
if(!cs.length){var n=d.createElement('p');n.className='none';n.textContent='Nothing found. Try another search.';g.appendChild(n)}
cs.forEach(function(c){var o=meta(c),m=o.m,e=function(s,t){var n=q(s,c);n&&(n.textContent=t)};
if(o.cat){e('.cat',o.cat.textContent);q('.cat',c).href=o.cat.href}
if(m.price!=null){var p=parseFloat(m.price)||0;e('.pr',p?'$'+p:'Free');c.dataset.price=p}else{c.classList.add('nm');c.dataset.price=0}
var r=parseFloat(m.rating)||0;c.dataset.rate=r;q('.st',c).style.setProperty('--r',(r/5*100)+'%');
m.reviews&&e('.rv','('+m.reviews+')');
c.dataset.sales=parseInt(m.sales,10)||0;m.sales&&e('.sl',m.sales+' Sales');
if(m.badge){var b=q('.bdg',c);b.textContent=m.badge;b.hidden=false}});
function sort(t){var k=t.dataset.s,dir=t.dataset.dir=(t.dataset.dir=='1'?'-1':'1'),l=qa('.card',g);
l.forEach(function(c,i){c._i=i});
l.sort(function(a,b){if(k=='new')return a._i-b._i;if(k=='price')return(a.dataset.price-b.dataset.price)*dir;if(k=='trend')return(b.dataset.cm-a.dataset.cm)||a._i-b._i;return(b.dataset[k]-a.dataset[k])||a._i-b._i});
l.forEach(function(c){g.appendChild(c)})}
qa('.tabs button').forEach(function(t){on(t,function(){qa('.tabs button').forEach(function(x){x.classList.remove('on')});t.classList.add('on');sort(t)})});
if(cs.some(function(c){return c.dataset.sales>0}))sort(q('.tabs [data-s=sales]'));
qa('.vw button').forEach(function(b){on(b,function(){qa('.vw button').forEach(function(x){x.classList.remove('on')});b.classList.add('on');g.classList.toggle('list',!!b.dataset.v)})});
}
var big=function(u,s){return u.replace(/\/s\d+(-c)?\//,'/'+s+'/')};
qa('.card img').forEach(function(i){if(/googleusercontent|bp\.blogspot/.test(i.src))i.src=big(i.src,'w640-h360-c')});
var pb=q('#pb');
if(pb&&q('.pm')){
var w=pb.textContent.trim().split(/\s+/).length,rd=q('.rd');rd&&(rd.textContent=Math.max(1,Math.round(w/220))+' min read');
var o=meta(q('.art')),act=q('#act');
if(act){['buy','preview'].forEach(function(k){var a=q('.btn-'+k,pb);if(a){var c=a.cloneNode(true);c.className=k=='buy'?'bb':'lp';act.appendChild(c)}});
if(!act.children.length)act.parentNode.removeChild(act)}
var bar=q('#bar'),h=d.documentElement;
addEventListener('scroll',function(){bar.style.width=(h.scrollTop/Math.max(1,h.scrollHeight-h.clientHeight)*100)+'%'},{passive:true});
on(q('#cp'),function(){navigator.clipboard&&navigator.clipboard.writeText(location.href);this.textContent='Copied'});
/* post features + sidebar */
var spec=q('table.spec',pb)||qa('table',pb).filter(function(t){return /last update|compatible browsers|layout|columns/i.test(t.textContent)})[0];
if(spec)spec.classList.add('spec');
var bu=q('.btn-buy',pb),pv=q('.btn-preview',pb),mm=o.m,pm=q('.pm');
function mk(t,c,x){var e=d.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e}
if(mm.sales){var s=mk('span','',mm.sales+' sales');pm.insertBefore(s,pm.children[1]||null)}
if(mm.rating){var rg=mk('span','rtg'),st=mk('span','st','\u2605\u2605\u2605\u2605\u2605');st.style.setProperty('--r',(parseFloat(mm.rating)/5*100)+'%');rg.appendChild(st);rg.appendChild(mk('b','',mm.rating));if(mm.reviews)rg.appendChild(mk('small','','('+mm.reviews+' reviews)'));pm.appendChild(rg)}
if(mm.badge)pm.appendChild(mk('span','ok',mm.badge));
qa('h2,h3,h4',pb).forEach(function(h){if(/feature/i.test(h.textContent)){h.classList.add('fh');var n=h.nextElementSibling;if(n&&n.tagName=='UL')n.classList.add('feat')}});
qa('p',pb).forEach(function(p){if(/do not forget to rate|rate this/i.test(p.textContent))p.classList.add('rate')});
qa('p.rate',pb).forEach(function(p){for(var k=0;k<5;k++){var i=mk('i','','\u2605');i.style.setProperty('--k',k);p.appendChild(i)}});
var an=qa('ul.feat,ul.show',pb),rv=[];
an.forEach(function(u){qa('li',u).forEach(function(li,i){li.style.setProperty('--i',i%7);rv.push(li)})});
qa('.fh,p.rate',pb).forEach(function(e){rv.push(e)});
rv.forEach(function(e){e.classList.add('rv')});
if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('v');io.unobserve(e.target)}})},{threshold:.12});rv.forEach(function(e){io.observe(e)})}else rv.forEach(function(e){e.classList.add('v')});
var art=q('.art'),h1=q('h1',art),ttl=h1?h1.textContent.trim():'',aA=q('.au a'),aN=aA?aA.textContent.trim():'',pvw=null,im=q('img',pb);
if(im&&pv){var iw=im.closest('a')||im,par=iw.parentNode;im.loading='eager';im.setAttribute('fetchpriority','high');
if(/googleusercontent|bp\.blogspot/.test(im.src))im.src=big(im.src,'w1200');
pvw=mk('div','pvw');pvw.appendChild(iw);if(par!==pb&&!par.textContent.trim()&&!q('img',par)&&par.parentNode)par.parentNode.removeChild(par);
var pb3=pv.cloneNode(true);pb3.className='pvb';pb3.textContent='Live Preview';pvw.appendChild(pb3)}
var side=mk('aside','side');
if(mm.price!=null||bu){
var bx=mk('div','bx pbox'),pp=mk('div','pp'),pw=mk('span','pw'),sup=mk('sup','','$'),pb2=mk('b'),base=parseFloat(mm.price)||0,ex=0,exw=0,qty=1,exOn=false;
if(mm.extend){var xp=String(mm.extend).split('/');ex=parseFloat(xp[0])||0;exw=parseFloat(xp[1])||0}
pw.appendChild(sup);pw.appendChild(pb2);pp.appendChild(mk('span','lic','Regular License'));pp.appendChild(pw);bx.appendChild(pp);
function show(){var t=base*qty+(exOn?ex:0);t=Math.round(t*100)/100;pb2.textContent=t?String(t):'Free';sup.style.display=t?'':'none';pb2.classList.remove('bump');void pb2.offsetWidth;pb2.classList.add('bump')}
var ul=mk('ul');['Quality checked','Free future updates','Support included'].forEach(function(t){ul.appendChild(mk('li','',t))});bx.appendChild(ul);
if(ex){var lb=mk('label','ext'),cb=mk('input');cb.type='checkbox';lb.appendChild(cb);lb.appendChild(mk('span','','Extend support to 12 months'));
if(exw)lb.appendChild(mk('s','','$'+exw));lb.appendChild(mk('b','','$'+ex));bx.appendChild(lb);cb.addEventListener('change',function(){exOn=cb.checked;show()})}
var qr=mk('div','qty'),qc=mk('div','qc'),mn=mk('button','','\u2212'),inp=mk('input'),pl=mk('button','','+');
mn.type=pl.type='button';mn.setAttribute('aria-label','Decrease');pl.setAttribute('aria-label','Increase');inp.type='number';inp.min=1;inp.max=99;inp.value=1;inp.setAttribute('aria-label','Quantity');
function sq(v){qty=Math.min(99,Math.max(1,parseInt(v,10)||1));inp.value=qty;show()}
on(mn,function(){sq(qty-1)});on(pl,function(){sq(qty+1)});inp.addEventListener('change',function(){sq(inp.value)});
qc.appendChild(mn);qc.appendChild(inp);qc.appendChild(pl);qr.appendChild(mk('label','','Quantity'));qr.appendChild(qc);bx.appendChild(qr);
if(bu){var c=bu.cloneNode(true);c.className='bb';c.textContent='\uD83D\uDED2 '+(bu.textContent.trim()||'Add to Cart');bx.appendChild(c)}
if(pv&&!pvw){var c2=pv.cloneNode(true);c2.className='lp';bx.appendChild(c2)}
bx.appendChild(mk('small','','Price is in US dollars and excludes tax and handling fees'));side.appendChild(bx);show()}
if(aA){var ax=mk('div','bx acd'),avt=mk('span','av',aN.charAt(0).toUpperCase()),pf=mk('a','pfb','View Portfolio');pf.href=aA.href;ax.appendChild(avt);ax.appendChild(mk('b','',aN));ax.appendChild(pf);side.appendChild(ax)}
if(spec){var dx=mk('div','bx');dx.appendChild(mk('h4','','Item Details'));dx.appendChild(spec);side.appendChild(dx)}
if(side.children.length){var cp=mk('p','cpr','\u00A9 All Rights Reserved '+(aN||''));cp.appendChild(d.createElement('br'));var cl=mk('a','','Contact support');cl.href='/p/support.html';cp.appendChild(cl);side.appendChild(cp)}
var cmN=parseInt(art.getAttribute('data-cm'),10)||0,tabs=mk('nav','ptabs');tabs.setAttribute('aria-label','Item sections');
function tb(t,h,n,o2){var a=mk('a',o2?'on':'',t);a.href=h;if(n)a.appendChild(mk('span','nb',n));return a}
var t1=tb('Item Details','#det',0,1),t3=tb('Comments','#comments',cmN||0,0);
tabs.appendChild(t1);tabs.appendChild(tb('Reviews','#comments',mm.reviews||0,0));tabs.appendChild(t3);tabs.appendChild(tb('Support','/p/support.html',0,0));
var fv=mk('button','sp fav'),fk='fav:'+location.pathname,heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3 4.5 6.7 4.5c2 0 3.6 1 5.3 3 1.7-2 3.3-3 5.3-3 3.7 0 5.8 3.9 4.3 7.3C19.5 16.4 12 21 12 21z"/></svg> ';
fv.type='button';function fs(x){fv.classList.toggle('on',x);fv.innerHTML=heart+(x?'Favorited':'Add to Favorites')}
var fx=false;try{fx=!!localStorage.getItem(fk)}catch(e){}fs(fx);
on(fv,function(){fx=!fx;fs(fx);try{fx?localStorage.setItem(fk,'1'):localStorage.removeItem(fk)}catch(e){}});
tabs.appendChild(fv);var shE=q('.sh');if(shE){shE.id='share';tabs.appendChild(tb('Share','#share',0,0))}
var cE=q('#comments');if(cE&&'IntersectionObserver' in window){new IntersectionObserver(function(es){es.forEach(function(x){t1.classList.toggle('on',!x.isIntersecting);t3.classList.toggle('on',x.isIntersecting)})},{rootMargin:'0px 0px -55% 0px'}).observe(cE)}
var kids=[].slice.call(art.children),hd=mk('header','phd'),col=mk('div','pcol'),seen=false;col.id='det';
kids.forEach(function(k){if(k===pb)seen=true;if(k.tagName=='SCRIPT')return;(seen?col:hd).appendChild(k)});
if(pvw)col.insertBefore(pvw,pb);
art.appendChild(hd);art.appendChild(tabs);art.appendChild(col);
if(side.children.length){art.appendChild(side);art.classList.add('two')}
if(mm.price!=null){try{var pj={"@context":"https://schema.org","@type":"Product",name:ttl,url:location.href.split('#')[0],offers:{"@type":"Offer",price:String(base),priceCurrency:"USD",availability:"https://schema.org/InStock",url:location.href.split('#')[0]}};
var ig=q('img',art);if(ig)pj.image=ig.src;if(aN)pj.brand={"@type":"Brand",name:aN};
if(mm.rating&&mm.reviews)pj.aggregateRating={"@type":"AggregateRating",ratingValue:mm.rating,reviewCount:parseInt(mm.reviews,10)||1};
var sj=d.createElement('script');sj.type='application/ld+json';sj.text=JSON.stringify(pj);d.head.appendChild(sj)}catch(e){}}
var lab=o.cat||q('.art .lb a'),box=q('#rel');
if(lab&&box&&window.fetch){fetch('/feeds/posts/default/-/'+encodeURIComponent(lab.textContent)+'?alt=json&max-results=5').then(function(r){return r.json()}).then(function(j){
var n=0;(j.feed.entry||[]).forEach(function(e){var l=e.link.filter(function(x){return x.rel=='alternate'})[0];if(!l||n>3||location.href.indexOf(l.href)==0)return;n++;
var a=d.createElement('a'),t=e.media$thumbnail,s=d.createElement('span');a.href=l.href;
if(t){var im=d.createElement('img');im.alt='';im.loading='lazy';im.src=big(t.url,'w320-h180-c');a.appendChild(im)}
s.textContent=e.title.$t;a.appendChild(s);box.appendChild(a)});
if(!n)box.parentNode.style.display='none'}).catch(function(){box.parentNode.style.display='none'})}else if(box)box.parentNode.style.display='none';
}
})();
